package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"go.uber.org/multierr"
)

// NewSQLite creates a new SQLite-based [LockStore].
func NewSQLite(tableName string) (LockStore, error) {
	if tableName == "" {
		return nil, errors.New("table name must not be empty")
	}
	return &sqliteStore{
		tableName: tableName,
	}, nil
}

var _ LockStore = (*sqliteStore)(nil)

type sqliteStore struct {
	tableName string
}

// SQLite has no native timestamp type, so lock timestamps are stored as UTC text generated by the
// database clock. The fixed-width layout keeps text comparisons (e.g., lease_expires_at < now) in
// chronological order.
const (
	sqliteTimeLayout = "2006-01-02 15:04:05.000"
	// sqliteNow is the current database time in sqliteTimeLayout.
	sqliteNow = `strftime('%Y-%m-%d %H:%M:%f', 'now')`
)

// sqliteLeaseExpiry returns the current database time plus a lease, where param is the query
// parameter bound to the lease as a strftime modifier (see formatDurationAsSQLiteModifier).
func sqliteLeaseExpiry(param string) string {
	return `strftime('%Y-%m-%d %H:%M:%f', 'now', ` + param + `)`
}

func (s *sqliteStore) TableExists(
	ctx context.Context,
	db *sql.DB,
) (bool, error) {
	schemaName, tableName := parseTableIdentifier(s.tableName)

	query := `SELECT EXISTS ( SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? )`
	if schemaName != "" {
		query = fmt.Sprintf(`SELECT EXISTS ( SELECT 1 FROM %s.sqlite_master WHERE type = 'table' AND name = ? )`, schemaName)
	}

	var exists bool
	if err := db.QueryRowContext(ctx, query, tableName).Scan(
		&exists,
	); err != nil {
		return false, fmt.Errorf("table exists: %w", err)
	}
	return exists, nil
}

func (s *sqliteStore) CreateLockTable(
	ctx context.Context,
	db *sql.DB,
) error {
	exists, err := s.TableExists(ctx, db)
	if err != nil {
		return fmt.Errorf("check lock table existence: %w", err)
	}
	if exists {
		return nil
	}

	query := fmt.Sprintf(`CREATE TABLE %s (
		lock_id INTEGER NOT NULL PRIMARY KEY,
		locked INTEGER NOT NULL DEFAULT 0,
		locked_at TEXT NULL,
		locked_by TEXT NULL,
		lease_expires_at TEXT NULL,
		updated_at TEXT NULL
	)`, s.tableName)
	if _, err := db.ExecContext(ctx, query); err != nil {
		// Double-check if another process created it concurrently
		if exists, checkErr := s.TableExists(ctx, db); checkErr == nil && exists {
			// Another process created it, that's fine!
			return nil
		}
		return fmt.Errorf("create lock table %q: %w", s.tableName, err)
	}
	return nil
}

func (s *sqliteStore) AcquireLock(
	ctx context.Context,
	db *sql.DB,
	lockID int64,
	lockedBy string,
	leaseDuration time.Duration,
) (*AcquireLockResult, error) {
	// Insert the lock row, or take over an existing one only if it is unlocked or its lease has
	// expired. Writes are serialized in SQLite, so this single statement is atomic. Requires SQLite
	// 3.35.0+ for RETURNING.
	query := fmt.Sprintf(`INSERT INTO %[1]s (lock_id, locked, locked_at, locked_by, lease_expires_at, updated_at)
	VALUES (?1, 1, %[2]s, ?2, %[3]s, %[2]s)
	ON CONFLICT (lock_id) DO UPDATE SET
		locked = 1,
		locked_at = %[2]s,
		locked_by = ?2,
		lease_expires_at = %[3]s,
		updated_at = %[2]s
	WHERE locked = 0 OR lease_expires_at < %[2]s
	RETURNING locked_by, lease_expires_at`, s.tableName, sqliteNow, sqliteLeaseExpiry("?3"))

	var returnedLockedBy, leaseExpiresAt string
	err := db.QueryRowContext(ctx, query,
		lockID,
		lockedBy,
		formatDurationAsSQLiteModifier(leaseDuration),
	).Scan(
		&returnedLockedBy,
		&leaseExpiresAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			// TODO(mf): should we return a special error type here?
			return nil, fmt.Errorf("acquire lock %d: already held by another instance", lockID)
		}
		return nil, fmt.Errorf("acquire lock %d: %w", lockID, err)
	}

	// Verify we got the lock by checking the returned locked_by matches our instance ID
	if returnedLockedBy != lockedBy {
		return nil, fmt.Errorf("acquire lock %d: acquired by %s instead of %s", lockID, returnedLockedBy, lockedBy)
	}
	expiresAt, err := parseSQLiteTime(leaseExpiresAt)
	if err != nil {
		return nil, fmt.Errorf("acquire lock %d: %w", lockID, err)
	}

	return &AcquireLockResult{
		LockedBy:       returnedLockedBy,
		LeaseExpiresAt: expiresAt,
	}, nil
}

func (s *sqliteStore) ReleaseLock(
	ctx context.Context,
	db *sql.DB,
	lockID int64,
	lockedBy string,
) (*ReleaseLockResult, error) {
	// Release lock only if it's held by the current instance
	query := fmt.Sprintf(`UPDATE %s SET
		locked = 0,
		locked_at = NULL,
		locked_by = NULL,
		lease_expires_at = NULL,
		updated_at = %s
	WHERE lock_id = ? AND locked_by = ?
	RETURNING lock_id`, s.tableName, sqliteNow)

	var returnedLockID int64
	err := db.QueryRowContext(ctx, query,
		lockID,
		lockedBy,
	).Scan(
		&returnedLockID,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			// TODO(mf): should we return a special error type here?
			return nil, fmt.Errorf("release lock %d: not held by this instance", lockID)
		}
		return nil, fmt.Errorf("release lock %d: %w", lockID, err)
	}

	// Verify the correct lock was released
	if returnedLockID != lockID {
		return nil, fmt.Errorf("release lock %d: returned lock ID %d does not match", lockID, returnedLockID)
	}

	return &ReleaseLockResult{
		LockID: returnedLockID,
	}, nil
}

func (s *sqliteStore) UpdateLease(
	ctx context.Context,
	db *sql.DB,
	lockID int64,
	lockedBy string,
	leaseDuration time.Duration,
) (*UpdateLeaseResult, error) {
	// Update lease expiration time for heartbeat, only if we own the lock
	query := fmt.Sprintf(`UPDATE %s SET
		lease_expires_at = %s,
		updated_at = %s
	WHERE lock_id = ?2 AND locked_by = ?3 AND locked = 1
	RETURNING lease_expires_at`, s.tableName, sqliteLeaseExpiry("?1"), sqliteNow)

	var leaseExpiresAt string
	err := db.QueryRowContext(ctx, query,
		formatDurationAsSQLiteModifier(leaseDuration),
		lockID,
		lockedBy,
	).Scan(
		&leaseExpiresAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, fmt.Errorf("failed to update lease for lock %d: not held by this instance", lockID)
		}
		return nil, fmt.Errorf("failed to update lease for lock %d: %w", lockID, err)
	}
	expiresAt, err := parseSQLiteTime(leaseExpiresAt)
	if err != nil {
		return nil, fmt.Errorf("failed to update lease for lock %d: %w", lockID, err)
	}

	return &UpdateLeaseResult{
		LeaseExpiresAt: expiresAt,
	}, nil
}

func (s *sqliteStore) CheckLockStatus(
	ctx context.Context,
	db *sql.DB,
	lockID int64,
) (*LockStatus, error) {
	query := fmt.Sprintf(`SELECT locked, locked_by, lease_expires_at, updated_at FROM %s WHERE lock_id = ?`, s.tableName)

	var (
		status                    LockStatus
		leaseExpiresAt, updatedAt sql.NullString
	)
	err := db.QueryRowContext(ctx, query,
		lockID,
	).Scan(
		&status.Locked,
		&status.LockedBy,
		&leaseExpiresAt,
		&updatedAt,
	)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, fmt.Errorf("lock %d not found", lockID)
		}
		return nil, fmt.Errorf("check lock status for %d: %w", lockID, err)
	}
	if status.LeaseExpiresAt, err = parseNullSQLiteTime(leaseExpiresAt); err != nil {
		return nil, fmt.Errorf("check lock status for %d: %w", lockID, err)
	}
	if status.UpdatedAt, err = parseNullSQLiteTime(updatedAt); err != nil {
		return nil, fmt.Errorf("check lock status for %d: %w", lockID, err)
	}

	return &status, nil
}

func (s *sqliteStore) CleanupStaleLocks(ctx context.Context, db *sql.DB) (_ []int64, retErr error) {
	query := fmt.Sprintf(`UPDATE %[1]s SET
		locked = 0,
		locked_at = NULL,
		locked_by = NULL,
		lease_expires_at = NULL,
		updated_at = %[2]s
	WHERE locked = 1 AND lease_expires_at < %[2]s
	RETURNING lock_id`, s.tableName, sqliteNow)

	rows, err := db.QueryContext(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("cleanup stale locks: %w", err)
	}
	defer func() {
		retErr = multierr.Append(retErr, rows.Close())
	}()

	var cleanedLocks []int64
	for rows.Next() {
		var lockID int64
		if err := rows.Scan(&lockID); err != nil {
			return nil, fmt.Errorf("scan cleaned lock ID: %w", err)
		}
		cleanedLocks = append(cleanedLocks, lockID)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate over cleaned locks: %w", err)
	}

	return cleanedLocks, nil
}

// formatDurationAsSQLiteModifier converts a time.Duration to a strftime modifier, e.g., "+30.000
// seconds".
func formatDurationAsSQLiteModifier(d time.Duration) string {
	return fmt.Sprintf("%+.3f seconds", d.Seconds())
}

func parseSQLiteTime(s string) (time.Time, error) {
	t, err := time.ParseInLocation(sqliteTimeLayout, s, time.UTC)
	if err != nil {
		return time.Time{}, fmt.Errorf("parse timestamp %q: %w", s, err)
	}
	return t, nil
}

func parseNullSQLiteTime(s sql.NullString) (*time.Time, error) {
	if !s.Valid {
		return nil, nil
	}
	t, err := parseSQLiteTime(s.String)
	if err != nil {
		return nil, err
	}
	return &t, nil
}
